mapper.select:
select t.person_name,t.person_name personName,t.res_param,t.res_param resParam,t.machine_id,t.machine_id
machineId,t.log_id,t.log_id logId,t.person_id,t.person_id personId,t.req_param,t.req_param
reqParam,t.state,t.community_id,t.community_id communityId,t.log_action,t.log_action logAction,
t.create_time createTime, lm.machine_name machineName, td.name logActionName, td1.name stateName
from lamp_machine_log t
left join lamp_machine lm on t.machine_id = lm.machine_id and lm.status_cd = '0'
left join t_dict td on t.log_action = td.status_cd and td.table_name = 'lamp_machine_operation' and td.table_columns = 'type'
left join t_dict td1 on t.state = td1.status_cd and td1.table_name = 'lift_machine_log' and td1.table_columns = 'state'
where 1 =1

    and t.person_name= #{personName}


    and t.res_param= #{resParam}


    and t.machine_id= #{machineId}


    and t.log_id= #{logId}


    and t.person_id= #{personId}


    and t.req_param= #{reqParam}


    and t.state= #{state}


    and t.community_id= #{communityId}


    and t.log_action= #{logAction}

order by t.create_time desc

    limit #{page}, #{row}

mapper.update:
update lamp_machine_log t set t.status_cd = #{statusCd}

    ,t.b_id = #{newBId}


    , t.person_name= #{personName}


    , t.res_param= #{resParam}


    , t.machine_id= #{machineId}


    , t.person_id= #{personId}


    , t.req_param= #{reqParam}


    , t.state= #{state}


    , t.community_id= #{communityId}


    , t.log_action= #{logAction}

where 1=1

    and t.log_id= #{logId}

